<script setup lang="ts">import { onMounted,ref } from 'vue';import { ElMessage,ElMessageBox } from 'element-plus';import { Edit3,Plus,Trash2 } from 'lucide-vue-next';import ResourceState from '@/components/common/ResourceState.vue';import { createAlarmRule,deleteAlarmRule,getAlarmRules,updateAlarmRule,type AlarmRule,type AlarmRulePayload } from '@/api/alarm';const data=ref<AlarmRule[]>([]),loading=ref(false),error=ref(''),dialog=ref(false),saving=ref(false);const blank=():AlarmRulePayload=>({ruleName:'',ruleCode:'',deviceType:'',metricName:'',comparisonOperator:'GTE',thresholdValue:0,alarmLevel:'MEDIUM',enabled:1,remark:''});const form=ref<AlarmRulePayload>(blank());const load=async()=>{loading.value=true;error.value='';try{data.value=(await getAlarmRules()).data}catch(e){error.value=e instanceof Error?e.message:'网络异常'}finally{loading.value=false}};const edit=(row?:AlarmRule)=>{form.value=row?{...row}:blank();dialog.value=true};const save=async()=>{if(!form.value.ruleName||!form.value.ruleCode||!form.value.metricName)return ElMessage.warning('请填写必填项');saving.value=true;try{form.value.id?await updateAlarmRule(form.value):await createAlarmRule(form.value);dialog.value=false;await load()}finally{saving.value=false}};const remove=async(row:AlarmRule)=>{await ElMessageBox.confirm(`确认删除规则“${row.ruleName}”？`,'删除确认',{type:'warning'});await deleteAlarmRule(row.id);await load()};onMounted(load)</script>
<template><article class="tech-panel"><div class="panel-head"><h2 class="panel-title">报警阈值规则</h2><button class="tech-button" @click="edit()"><Plus :size="13"/>新增规则</button></div><ResourceState :loading="loading" :error="error" :empty="!data.length" @retry="load"><el-table :data="data"><el-table-column prop="ruleCode" label="规则编码"/><el-table-column prop="ruleName" label="规则名称"/><el-table-column prop="deviceType" label="设备类型"/><el-table-column prop="metricName" label="监测指标"/><el-table-column label="条件"><template #default="{row}">{{ row.comparisonOperator }} {{ row.thresholdValue }}</template></el-table-column><el-table-column prop="alarmLevel" label="报警等级"/><el-table-column label="状态"><template #default="{row}">{{ row.enabled===1?'启用':'停用' }}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link @click="edit(row)"><Edit3 :size="13"/>修改</el-button><el-button link type="danger" @click="remove(row)"><Trash2 :size="13"/>删除</el-button></template></el-table-column></el-table></ResourceState></article><el-dialog v-model="dialog" :title="form.id?'修改报警规则':'新增报警规则'" width="min(700px,92vw)"><el-form :model="form" label-width="100px" class="rule-form"><el-form-item label="规则名称" required><el-input v-model="form.ruleName"/></el-form-item><el-form-item label="规则编码" required><el-input v-model="form.ruleCode"/></el-form-item><el-form-item label="设备类型"><el-select v-model="form.deviceType" clearable><el-option label="全部设备" value=""/><el-option label="塔吊" value="TOWER_CRANE"/><el-option label="环境设备" value="DUST"/></el-select></el-form-item><el-form-item label="监测指标" required><el-select v-model="form.metricName"><el-option v-for="m in ['pm25','pm10','noiseDb','temperature','humidity','windSpeed']" :key="m" :label="m" :value="m"/></el-select></el-form-item><el-form-item label="比较符"><el-select v-model="form.comparisonOperator"><el-option v-for="o in ['GT','GTE','LT','LTE','EQ']" :key="o" :label="o" :value="o"/></el-select></el-form-item><el-form-item label="阈值"><el-input-number v-model="form.thresholdValue"/></el-form-item><el-form-item label="报警等级"><el-select v-model="form.alarmLevel"><el-option label="提示" value="LOW"/><el-option label="一般" value="MEDIUM"/><el-option label="严重" value="HIGH"/><el-option label="紧急" value="CRITICAL"/></el-select></el-form-item><el-form-item label="是否启用"><el-switch v-model="form.enabled" :active-value="1" :inactive-value="0"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark"/></el-form-item></el-form><template #footer><button class="tech-button" :disabled="saving" @click="save">保存</button></template></el-dialog></template><style scoped>.rule-form{display:grid;grid-template-columns:1fr 1fr}@media(max-width:650px){.rule-form{grid-template-columns:1fr}}</style>

